#!/bin/bash
set -euo pipefail
cd /work/live-vector/ATOM
export PYTHONPATH=/work/live-vector/ATOM
export HIP_VISIBLE_DEVICES=0 ATOM_DSV4_HYBRID=0 ATOM_DSV4_HYBRID_ATTN=0 ATOM_DSV4_HYBRID_GEMM=0 ATOM_DSV4_FLASH_MOE=0 ATOM_DSV4_MONO=0 ATOM_MONO_ENABLE=0
export ATOM_VECTOR_UNFUSED=1 ATOM_VECTOR_CHECK=1 ATOM_VECTOR_NATIVE_STRICT=0 ATOM_VECTOR_REFERENCE_CHECK=1
export HSA_ENABLE_SDMA=1 HSA_USE_SVM=1 HSA_XNACK=1 AITER_DISABLE_KERNARG_PRELOAD=0 ATOM_USE_TRITON_MOE=1 ATOM_USE_UNIFIED_ATTN=1 ATOM_FORCE_ATTN_TRITON=1 ATOM_LOADER_USE_THREADPOOL=1 AITER_ROPE_TRITON_BACKEND=1 ATOM_USE_TRITON_GEMM=1 ENABLE_CK=0 AITER_USE_OPUS_MOE_SORTING=1 AITER_FORCE_A8W4=0 AITER_USE_GROUPED_GEMM=1 ATOM_USE_AITER_TRITON_ATTN=1 AITER_TRITON_USE_HERD=1 ATOM_USE_TRITON_MOE_DECODE=1 ATOM_FP8_BLOCKSCALE_USE_E8M0_SCALE=1 ATOM_MOE_GU_ITLV=1
export ATOM_ENABLE_DS_QKNORM_FUSION=0 ATOM_ENABLE_DS_INPUT_RMSNORM_QUANT_FUSION=0 ATOM_ENABLE_DS_QKNORM_QUANT_FUSION=0
export TRITON_CACHE_DIR=/work/flash/triton-cache
ulimit -c 0
python -m atom.entrypoints.openai_server -tp 1 --model /data/DeepSeek-V4-Flash --kv_cache_dtype bf16 --index-cache-dtype fp8 --no-enable_prefix_caching --disable_uvicorn_access_log --max-num-seqs 128 --enforce-eager > /work/live-vector/validation-server.log 2>&1
